Use `pg` (node-postgres) with `Pool`:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Pool sizing
  max: 20,                    // max connections (default 10)
  min: 2,                     // keep alive minimum
  // Timeouts (ms)
  connectionTimeoutMillis: 5000,   // fail fast if can't get connection
  idleTimeoutMillis: 30000,        // release idle connections after 30s
  query_timeout: 10000,            // per-query timeout
  statement_timeout: 10000,        // server-side statement timeout
  // SSL (prod)
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: true } : false,
});

// Pool-level error — catch unclaimed client errors
pool.on('error', (err, client) => {
  console.error('Idle client error:', err);
});
```

**Query wrapper with proper release:**

```javascript
export async function query(text, params) {
  const client = await pool.connect();
  try {
    const result = await client.query(text, params);
    return result;
  } finally {
    client.release();  // always release, even on error
  }
}
```

**Or use `pool.query` for one-shot queries** — handles acquire/release automatically:

```javascript
const { rows } = await pool.query('SELECT * FROM users WHERE id = $1', [userId]);
```

**Transaction pattern:**

```javascript
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('INSERT INTO orders ...', [...]);
  await client.query('UPDATE inventory ...', [...]);
});
```

**Graceful shutdown:**

```javascript
process.on('SIGTERM', async () => {
  await pool.end();  // drains pool before exit
  process.exit(0);
});
```

Key points:
- `connectionTimeoutMillis` — how long to wait for free slot in pool (not TCP connect)
- `query_timeout` — client-side, throws if exceeded
- `statement_timeout` — server-side, PostgreSQL cancels query
- Always `release()` in `finally` — leaked clients exhaust pool silently
- `pool.query` safer for simple queries; manual `connect()` needed for transactions
